"""Own visual controller for the single push-wall episode.
Only public RGB/depth/calibration, target and proprioception are used.
The interactive command log is saved alongside this script for the record.
"""
import sys,json,time
from pathlib import Path
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot

OUT=Path('/app/output'); OUT.mkdir(exist_ok=True)
class Controller:
    def __init__(self):
        self.r=Robot(); self.spec=self.r.spec(); self.cams=list(self.spec['cameras']); self.dt=self.spec['control_dt']; self.index=0
        self.obs=self.r.get_obs(cameras=self.cams,include_depth=True)
        self.correction={}
        # Anchor the camera's horizontal origin to the visible task marker.
        # The nominal calibration has a small horizontal eye offset.
        for c in self.cams:
            xyz=self.cloud(self.obs,c,correct=False); rgb=self.obs.last[c].astype(float)
            green=(rgb[:,:,1]>100)&(rgb[:,:,1]>1.5*rgb[:,:,0])&(rgb[:,:,1]>1.5*rgb[:,:,2])
            if green.any():
                center=np.median(xyz[green],axis=0); target=np.array(self.obs.meta['task']['target_pos'])
                right=np.array(self.obs.meta['cameras'][c]['cam2world_gl'])[:3,0]
                self.correction[c]=right*np.dot(target-center,right)
            else:
                self.correction[c]=np.zeros(3)
        # Front marker is hidden by wall: same eye-offset correction measured in top view.
        if np.linalg.norm(self.correction['front'])<1e-6:
            right=np.array(self.obs.meta['cameras']['front']['cam2world_gl'])[:3,0]
            self.correction['front']=right*np.linalg.norm(self.correction['topview'])
        self.save('start')
    def cloud(self,o,c,correct=True):
        d=o.depth[c].astype(float).squeeze(); K=np.array(o.meta['cameras'][c]['intrinsic_cv']); C=np.array(o.meta['cameras'][c]['cam2world_gl']); v,u=np.indices(d.shape)
        p=np.stack([(u-K[0,2])*d/K[0,0],-(v-K[1,2])*d/K[1,1],-d],axis=-1)@C[:3,:3].T+C[:3,3]
        return p+self.correction.get(c,np.zeros(3)) if correct else p
    def state(self):
        p=self.obs.meta['proprio']; return dict(zip(p['layout'],p['now']))
    def locate(self):
        estimates={}
        for c in self.cams:
            rgb=self.obs.last[c].astype(float); xyz=self.cloud(self.obs,c)
            red=(rgb[:,:,0]>55)&(rgb[:,:,0]>1.8*rgb[:,:,1])&(rgb[:,:,0]>1.8*rgb[:,:,2])
            mask=red&(xyz[:,:,2]>.008)&(xyz[:,:,2]<.055)&(xyz[:,:,1]>.52)&(xyz[:,:,1]<.97)&(abs(xyz[:,:,0])<.3)
            p=xyz[mask]
            if len(p)>5:
                estimates[c]={'n':len(p),'median':np.median(p,axis=0).tolist(),'min':p.min(0).tolist(),'max':p.max(0).tolist()}
        return estimates
    def save(self,label):
        d=OUT/f'run_{self.index:03d}_{label}'; self.obs.save(str(d))
        for c,im in self.obs.last.items(): Image.fromarray(im).save(str(d/f'{c}.png'))
        s=self.state(); print(json.dumps({'saved':str(d),'steps':self.obs.meta['control_steps'],'time_left':self.obs.meta['time_left_s'],'tcp':[s['tcp_'+a] for a in 'xyz'],'mocap':[s['mocap_'+a] for a in 'xyz'],'opening':s['gripper_opening'],'object_surface':self.locate()}),flush=True)
        self.index+=1
    def observe(self,label='observe'):
        self.obs=self.r.get_obs(cameras=self.cams,include_depth=True); self.save(label)
    def submit(self,A,label):
        A=np.asarray(A,dtype=np.float64)
        self.obs=self.r.submit('ee_delta',A,dt=self.dt,cameras=self.cams,video='both',video_fps=15,include_depth=True,note=label)
        self.save(label)
    def move(self,tcp,speed=.2,grip=1,settle=20,label='move'):
        s=self.state(); actual=np.array([s['tcp_'+a] for a in 'xyz']); mocap=np.array([s['mocap_'+a] for a in 'xyz']); goal=np.array(tcp)+mocap-actual
        delta=goal-mocap; n=max(1,int(np.ceil(np.max(np.abs(delta))/(.01*speed)))); action=np.r_[delta/(.01*n),grip]; A=np.tile(action,(n,1))
        if settle: A=np.vstack([A,np.tile([0,0,0,grip],(settle,1))])
        self.submit(A,label)
    def delta(self,xyz,n,grip=1,label='delta',settle=0):
        A=np.tile(np.r_[xyz,grip],(n,1))
        if settle: A=np.vstack([A,np.tile([0,0,0,grip],(settle,1))])
        self.submit(A,label)

if __name__=='__main__':
    ctl=Controller(); print('READY',flush=True)
    for line in sys.stdin:
        try:
            cmd=json.loads(line); (OUT/'commands.jsonl').open('a').write(json.dumps(cmd)+'\n')
            op=cmd.pop('op')
            if op=='stop': print('STOPPED: no further control steps.',flush=True); break
            getattr(ctl,op)(**cmd)
        except Exception as e:
            print(type(e).__name__+': '+str(e),flush=True)
